create or replace function public.tax_process_sandbox(p_document uuid) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$declare d public.tax_documents%rowtype;o public.tax_organizations%rowtype;h text;resp jsonb;begin if public.current_finance_role() not in('OWNER','FINANCE_MANAGER') then raise exception 'Not authorized';end if;select * into d from public.tax_documents where id=p_document for update;select * into o from public.tax_organizations where id=d.organization_id;if d.status<>'READY' then raise exception 'Document is not READY';end if;if o.environment<>'SANDBOX' then raise exception 'Sandbox adapter cannot process Production configuration';end if;h:=encode(extensions.digest(d.payload::text,'sha256'),'hex');resp:=jsonb_build_object('adapter','SANDBOX','accepted',true,'simulation',true,'request_hash',h);insert into public.tax_submission_attempts(document_id,adapter,request_hash,response_status,response_body,attempted_by)values(d.id,'SANDBOX',h,200,resp,auth.uid());update public.tax_documents set status='ACCEPTED',eta_uuid='SANDBOX-'||d.id,response_payload=resp,attempt_count=attempt_count+1,last_attempt_at=now(),updated_at=now(),updated_by=auth.uid() where id=d.id;insert into public.audit_events(table_name,record_id,action,old_data,new_data,changed_by)values('tax_documents',d.id::text,'SANDBOX_ACCEPT',jsonb_build_object('status',d.status),resp,auth.uid());return resp;end$$;
revoke all on function public.tax_process_sandbox(uuid) from public,anon;grant execute on function public.tax_process_sandbox(uuid) to authenticated;
